// Before creating directories
size_t depth = std::count(fsFileName.string().begin(), fsFileName.string().end(), filesystem::path::preferred_separator);
if (depth > MAX_ALLOWED_DEPTH) {
    LOG_ERROR << "Path depth exceeds maximum allowed";
    return -1;
}

// Example of rate limiting (simplified, consider using a more robust method)
