### **2. Insufficient Error Handling (Resource Leak)**

* **Vulnerability:** Resource Leak
* **Response Type:** Mitigation
* **Reason:** The function may not free the socket buffer (`skb`) in all failure paths.
* **Action:**
	+ Introduce a unified error handling path to ensure `skb` is freed in all failure scenarios.
```c
static int rsi_send_beacon(struct rsi_common *common)
{
    struct sk_buff *skb = NULL;
    int ret = 0;

    if (!common) {
        rsi_dbg(ERR_ZONE, "common is NULL\n");
        return -EINVAL;
    }

    skb = dev_alloc_skb(MAX_MGMT_PKT_SIZE);
    if (!skb)
        return -ENOMEM;

    memset(skb->data, 0, MAX_MGMT_PKT_SIZE);

    dword_align_bytes = ((unsigned long)skb->data & 0x3f);
    if (dword_align_bytes)
        skb_pull(skb, (64 - dword_align_bytes));

    ret = rsi_prepare_beacon(common, skb);
    if (ret) {
        rsi_dbg(ERR_ZONE, "Failed to prepare beacon\n");
        goto error;
    }

    skb_queue_tail(&common->tx_queue[MGMT_BEACON_Q], skb);
    rsi_set_event(&common->tx_thread.event);
    rsi_dbg(DATA_TX_ZONE, "%s: Added to beacon queue\n", __func__);

    return 0;

error:
    dev_kfree_skb(skb);
    return ret; // or -EINVAL, depending on the desired error propagation
}
```

